// Stage 5.3.2 — Recalculate portfolio health score
// Health formula: ((onTrack * 1.0) + (dlp * 0.9) + (atRisk * 0.5)) / totalProjects * 100
const now = new Date();

// Gather all collection data from upstream nodes
const allData = $input.all();
const projects = [];
const tasks = [];
const bgs = [];
const issues = [];

for (const item of allData) {
  const d = item.json;
  if (Array.isArray(d)) {
    d.forEach(doc => {
      if (doc.status && (doc.priority || doc.projectId)) {
        if (doc.projectId && !doc.issuingBank && !doc.dueDate) issues.push(doc);
        else if (doc.projectId && doc.dueDate) tasks.push(doc);
        else if (!doc.projectId && doc.issuingBank) bgs.push(doc);
        else projects.push(doc);
      } else {
        projects.push(doc);
      }
    });
  }
}

// Calculate health metrics (matching dashboard.js formula)
let onTrackCount = 0;
let atRiskCount = 0;
let dlpCount = 0;
projects.forEach(p => {
  if (p.status === 'completed') dlpCount++;
  else if (p.status === 'active') onTrackCount++;
  else atRiskCount++;
});

const totalProjects = projects.length || 1;
const rawHealthScore = (((onTrackCount * 1.0) + (dlpCount * 0.9) + (atRiskCount * 0.5)) / totalProjects) * 100;
const healthScore = rawHealthScore.toFixed(1);
const healthStatusLabel = rawHealthScore >= 80 ? 'Optimal' : rawHealthScore >= 70 ? 'Stable' : 'Attention Needed';

// Task metrics
const completedTasks = tasks.filter(t => t.status === 'done').length;
const overdueTasks = tasks.filter(t => {
  if (!t.dueDate || t.status === 'done') return false;
  return new Date(t.dueDate) < now;
}).length;
const taskCompletionRate = tasks.length > 0 ? ((completedTasks / tasks.length) * 100).toFixed(1) : '0.0';

// BG risk metrics
const activeBGs = bgs.filter(b => b.status !== 'released');
const criticalBGs = activeBGs.filter(b => b.daysLeft != null && b.daysLeft <= 30);
const warningBGs = activeBGs.filter(b => b.daysLeft != null && b.daysLeft > 30 && b.daysLeft <= 60);

// Issue metrics
const openIssues = issues.filter(i => i.status === 'open').length;

const healthSnapshot = {
  calculatedAt: now.toISOString(),
  portfolioHealth: {
    score: parseFloat(healthScore),
    label: healthStatusLabel,
    onTrack: onTrackCount,
    atRisk: atRiskCount,
    inDLP: dlpCount,
    totalProjects: projects.length
  },
  taskMetrics: {
    total: tasks.length,
    completed: completedTasks,
    overdue: overdueTasks,
    completionRate: parseFloat(taskCompletionRate)
  },
  bgRisk: {
    totalActive: activeBGs.length,
    critical: criticalBGs.length,
    warning: warningBGs.length,
    criticalBGs: criticalBGs.map(b => ({ref: b.ref || b.id, projectName: b.projectName, daysLeft: b.daysLeft}))
  },
  issueMetrics: {
    open: openIssues
  },
  alerts: []
};

// Generate alerts if thresholds breached
if (rawHealthScore < 70) healthSnapshot.alerts.push({level: 'warning', message: `Portfolio health score ${healthScore}% is below 70% threshold.`});
if (criticalBGs.length > 0) healthSnapshot.alerts.push({level: 'critical', message: `${criticalBGs.length} Bank Guarantee(s) expiring within 30 days.`});
if (overdueTasks > 5) healthSnapshot.alerts.push({level: 'warning', message: `${overdueTasks} overdue tasks detected.`});

return [{json: healthSnapshot}];

const data = $input.first().json;
const collection = 'healthSnapshots';
const docId = "health-" + Date.now();

function toFirestoreValue(val) {
  if (val === null || val === undefined) return { nullValue: null };
  if (typeof val === 'string') return { stringValue: val };
  if (typeof val === 'number') return Number.isInteger(val) ? { integerValue: String(val) } : { doubleValue: val };
  if (typeof val === 'boolean') return { booleanValue: val };
  if (Array.isArray(val)) return { arrayValue: { values: val.map(v => toFirestoreValue(v)) } };
  if (typeof val === 'object') {
    const fields = {};
    for (const [k, v] of Object.entries(val)) fields[k] = toFirestoreValue(v);
    return { mapValue: { fields } };
  }
  return { stringValue: String(val) };
}

const fields = {};
const clean = { ...data };
delete clean._firestoreCollection;
delete clean._firestoreDocId;
for (const [key, val] of Object.entries(clean)) fields[key] = toFirestoreValue(val);

return [{ json: { _firestoreCollection: collection, _firestoreDocId: docId, _firestoreBody: { fields } } }];

