// Parse Firestore REST API response to plain JSON
const response = $input.first().json;
const documents = response.documents || [];
const results = [];

function fromFirestoreValue(val) {
  if (!val) return null;
  if (val.nullValue !== undefined) return null;
  if (val.stringValue !== undefined) return val.stringValue;
  if (val.integerValue !== undefined) return parseInt(val.integerValue, 10);
  if (val.doubleValue !== undefined) return val.doubleValue;
  if (val.booleanValue !== undefined) return val.booleanValue;
  if (val.arrayValue !== undefined) return (val.arrayValue.values || []).map(v => fromFirestoreValue(v));
  if (val.mapValue !== undefined) {
    const obj = {};
    for (const [k, v] of Object.entries(val.mapValue.fields || {})) obj[k] = fromFirestoreValue(v);
    return obj;
  }
  if (val.timestampValue !== undefined) return val.timestampValue;
  return null;
}

for (const doc of documents) {
  const fields = doc.fields || {};
  const parsed = {};
  for (const [key, val] of Object.entries(fields)) {
    parsed[key] = fromFirestoreValue(val);
  }
  const docName = doc.name || '';
  parsed.id = docName.split('/').pop();
  parsed._firestoreDocPath = docName;
  results.push({ json: parsed });
}

return results.length > 0 ? results : [{ json: { _empty: true, _collection: 'projects' } }];

